INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('31', 'Pilihlah kesimpulan yang paling tepat dari semua pernyataan atau premis yang tersedia pada setiap soal!', 'Ibrahim pandai fisika. <br/> Orang yang pandai fisika pasti padndai matematika. <br/> Orang yang pandai matematika, tidak pandai berbahasa Jepang. <br/> Maka….', '');
