INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('33', 'Pilihlah kesimpulan yang paling tepat dari semua pernyataan atau premis yang tersedia pada setiap soal!', 'Sebagian Intan bersifat kuat. <br/> Semua yang kuat tidak mudah patah. <br/> maka....', '');
INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('34', 'Pilihlah kesimpulan yang paling tepat dari semua pernyataan atau premis yang tersedia pada setiap soal!', 'Hewan yang termasuk mamalia berkembang biak dengan cara beranak. <br/> Buaya berkembang biak dengan cara bertelur. <br/> Simpulan yang tepat adalah...', '');
