INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('37', 'Pilihlah kesimpulan yang paling tepat dari semua pernyataan atau premis yang tersedia pada setiap soal!', 'Semua menu makanan restoran B diolah dari bahan organik. <br/>  Sebagian menu makanan diolah tanpa menggunakan minyak (tidak digoreng). <br/> Maka….', '');
INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('38', 'Pilihlah kesimpulan yang paling tepat dari semua pernyataan atau premis yang tersedia pada setiap soal!', 'Semua radio memakai baterai. <br/> Sebagian radio tidak memakai antena panjang. <br/> Maka….', '');
INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('39', 'Pilihlah kesimpulan yang paling tepat dari semua pernyataan atau premis yang tersedia pada setiap soal!', 'Bila semua X adalah A. <br/> Sebagian X adalah B. <br/> Maka.....', '');
