INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('43', 'Sembilan peserta rapat A, B, C, D, E, F, G, H, dan I duduk pada suatu ruangan yang terdiri dari 3 baris, dengan susunan:<br/> -Baris 1 : 1  2  3<br/>-Baris 2 : 4  5  6<br/>-Baris 3 : 7  8  9<br/>Setiap baris kursi memiliki lorong dikedua ujung. Pengaturan tempat duduk sebagai berikut:<br/>1.I tidak duduk di baris yang sama dengan A.<br/>2.C duduk tepat di belakang kursi G.<br/>3.B duduk tepat di sebelah kanan dari kursi D.<br/>4.H duduk tepat di sebelah kiri C.<br/>5.A duduk tepat di depan D.', 'Peserta rapat yang duduk di kursi 1, 2 dan 3 adalah ....', '');
INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('44', 'Sembilan peserta rapat A, B, C, D, E, F, G, H, dan I duduk pada suatu ruangan yang terdiri dari 3 baris, dengan susunan:<br/> -Baris 1 : 1  2  3<br/>-Baris 2 : 4  5  6<br/>-Baris 3 : 7  8  9<br/>Setiap baris kursi memiliki lorong dikedua ujung. Pengaturan tempat duduk sebagai berikut:<br/>1.I tidak duduk di baris yang sama dengan A.<br/>2.C duduk tepat di belakang kursi G.<br/>3.B duduk tepat di sebelah kanan dari kursi D.<br/>4.H duduk tepat di sebelah kiri C.<br/>5.A duduk tepat di depan D.', 'Jika F duduk di kursi 2, manakah yang benar?', '');
INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('45', 'Sembilan peserta rapat A, B, C, D, E, F, G, H, dan I duduk pada suatu ruangan yang terdiri dari 3 baris, dengan susunan:<br/> -Baris 1 : 1  2  3<br/>-Baris 2 : 4  5  6<br/>-Baris 3 : 7  8  9<br/>Setiap baris kursi memiliki lorong dikedua ujung. Pengaturan tempat duduk sebagai berikut:<br/>1.I tidak duduk di baris yang sama dengan A.<br/>2.C duduk tepat di belakang kursi G.<br/>3.B duduk tepat di sebelah kanan dari kursi D.<br/>4.H duduk tepat di sebelah kiri C.<br/>5.A duduk tepat di depan D.', 'Jika I duduk pada kursi 9, manakah pernyataan berikut yang benar?', '');
INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('46', 'Sembilan peserta rapat A, B, C, D, E, F, G, H, dan I duduk pada suatu ruangan yang terdiri dari 3 baris, dengan susunan:<br/> -Baris 1 : 1  2  3<br/>-Baris 2 : 4  5  6<br/>-Baris 3 : 7  8  9<br/>Setiap baris kursi memiliki lorong dikedua ujung. Pengaturan tempat duduk sebagai berikut:<br/>1.I tidak duduk di baris yang sama dengan A.<br/>2.C duduk tepat di belakang kursi G.<br/>3.B duduk tepat di sebelah kanan dari kursi D.<br/>4.H duduk tepat di sebelah kiri C.<br/>5.A duduk tepat di depan D.', 'Manakah pasangan peserta rapat berikut yang bisa duduk pada baris yang sama?', '');
INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('47', 'Sembilan peserta rapat A, B, C, D, E, F, G, H, dan I duduk pada suatu ruangan yang terdiri dari 3 baris, dengan susunan:<br/> -Baris 1 : 1  2  3<br/>-Baris 2 : 4  5  6<br/>-Baris 3 : 7  8  9<br/>Setiap baris kursi memiliki lorong dikedua ujung. Pengaturan tempat duduk sebagai berikut:<br/>1.I tidak duduk di baris yang sama dengan A.<br/>2.C duduk tepat di belakang kursi G.<br/>3.B duduk tepat di sebelah kanan dari kursi D.<br/>4.H duduk tepat di sebelah kiri C.<br/>5.A duduk tepat di depan D.', 'Jika B dan G duduk pada baris yang sama, manakah dari pernyataan berikut yang benar?', '');
INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('48', 'Ada 7 kotak peti, masing-masing diberi nomor 1 sampai 7. Buah jambu, melon, semangka, jeruk, mangga dan durian akan dimasukkan ke dalam peti-peti tersebut. dengan aturan sebagai berikut:<br/>-Durian harus dimasukkan ke peti nomor 4.<br/>-Semangka tidak boleh diletakkan tepat di samping melon.<br/>-Jeruk harus diletakkan di samping mangga', 'Jika melon diletakkan di peti nomor 2, maka mana yang tidak boleh dilakukan?', '');
INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('49', 'Ada 7 kotak peti, masing-masing diberi nomor 1 sampai 7. Buah jambu, melon, semangka, jeruk, mangga dan durian akan dimasukkan ke dalam peti-peti tersebut. dengan aturan sebagai berikut:<br/>-Durian harus dimasukkan ke peti nomor 4.<br/>-Semangka tidak boleh diletakkan tepat di samping melon.<br/>-Jeruk harus diletakkan di samping mangga', 'Jika semangka diletakkan di peti nomor 6, dan jambu diletakkan di peti nomor 7, maka peti mana yang kosong?', '');
INSERT INTO `questions` (`id`, `description`, `question`, `media_path`) VALUES ('50', 'Ada 7 kotak peti, masing-masing diberi nomor 1 sampai 7. Buah jambu, melon, semangka, jeruk, mangga dan durian akan dimasukkan ke dalam peti-peti tersebut. dengan aturan sebagai berikut:<br/>-Durian harus dimasukkan ke peti nomor 4.<br/>-Semangka tidak boleh diletakkan tepat di samping melon.<br/>-Jeruk harus diletakkan di samping mangga', 'Jika semangka diletakkan di peti nomor 5, jambu diletakkan di peti nomor 6 dan melon diletakkan di peti nomor 7, maka ada berapa kemungkinan pengaturan letak buah sesuai dengan aturan di atas?', '');
